import{_ as a,o as t,c as r,a2 as s}from"./chunks/framework.BvlN9b-o.js";const b=JSON.parse('{"title":"跟做：确定性性能门禁","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/perf-gates.md","filePath":"tutorials/perf-gates.md"}'),d={name:"tutorials/perf-gates.md"};function o(c,e,n,i,l,p){return t(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="跟做-确定性性能门禁" tabindex="-1">跟做：确定性性能门禁 <a class="header-anchor" href="#跟做-确定性性能门禁" aria-label="Permalink to &quot;跟做：确定性性能门禁&quot;">​</a></h1><p>本章回答“这个模板怎么保证性能不悄悄退化”。模板不跑秒表：墙钟时间在共享的 CI 机器上抖动，压测报告无法成为每次提交的门槛。<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/2ee9415a88a784ded5dd07b8a1dcc3e8b11a7ec2/docs/saas-template-architecture-spec.md" target="_blank" rel="noreferrer">规范 §17</a> 的做法是把性能写成**<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/2ee9415a88a784ded5dd07b8a1dcc3e8b11a7ec2/CONTEXT.md" target="_blank" rel="noreferrer">性能合同</a>**——一次操作允许写几行、几次数据库往返、返回多大载荷、构建产物多重——然后让每次 CI 按行数、次数与字节数验收。这些数要么达标要么失败，从不“看情况”。负载、饱和与浸泡是后续里程碑的报告工作，不在本版门禁里。</p><h2 id="_1-预算合同-两份测试清单" tabindex="-1">1. 预算合同：两份测试清单 <a class="header-anchor" href="#_1-预算合同-两份测试清单" aria-label="Permalink to &quot;1. 预算合同：两份测试清单&quot;">​</a></h2><p>预算钉在集成测试里，走与其他行为测试完全相同的公开 HTTP 接口：</p><table tabindex="0"><thead><tr><th>文件</th><th>归属</th><th>钉住什么</th></tr></thead><tbody><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/2ee9415a88a784ded5dd07b8a1dcc3e8b11a7ec2/apps/api/tests/perf_registration.rs" target="_blank" rel="noreferrer">perf_registration.rs</a></td><td>Core（删例后继续生效）</td><td>注册 201 恰好写 1 用户 + 1 凭证 + 1 有效成员身份 + 1 条 <code>identity.register</code> 审计；会话是另一份合同、单独计数；0 任务、0 通知；重复注册 409 且什么都没写</td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/2ee9415a88a784ded5dd07b8a1dcc3e8b11a7ec2/apps/api/tests/perf_documents.rs" target="_blank" rel="noreferrer">perf_documents.rs</a></td><td>示例（登记在<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/2ee9415a88a784ded5dd07b8a1dcc3e8b11a7ec2/examples/knowledge-base/manifest.json" target="_blank" rel="noreferrer">所有权清单</a>）</td><td>文档列表往返次数不随数据量增长（上限 4 次，无 N+1）；列表载荷 ≤256 KiB 且永不携带正文；创建 = +1 文档 +1 审计，首次个人库准备恰好发生一次（并发下也如此）；导出请求 = 1 导出 + 1 任务 + 1 审计 + 1 意图行，幂等重放不产生重复</td></tr></tbody></table><p>每个测试都是行数断言，不是时间断言：<code>SELECT count(*)</code> 直接问数据库“这次操作到底写了什么”。拒绝路径同样有预算——重复注册写入零行，导出重放不重复副作用。</p><p>往返次数不是估出来的。sqlx 把每条执行的语句作为 <code>sqlx::query</code> 事件发出，测试装一个订阅者数事件即得精确计数。这里有个值得记下的坑：tracing 的 interest 缓存在 callsite 首次触发时定型，并行测试里先触发的 callsite 可能被缓存为“永不”，之后整个进程静默——所以测试装的是<strong>全局</strong>订阅者（无条件报 <code>Interest::sometimes</code>），按线程 id 计数，绕开缓存。</p><h2 id="_2-包体门禁" tabindex="-1">2. 包体门禁 <a class="header-anchor" href="#_2-包体门禁" aria-label="Permalink to &quot;2. 包体门禁&quot;">​</a></h2><p>包体门禁 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/2ee9415a88a784ded5dd07b8a1dcc3e8b11a7ec2/scripts/perf-bundle.mjs" target="_blank" rel="noreferrer">perf-bundle.mjs</a> 是 <code>just perf-ci</code> 的第一半：真实执行 <code>vite build</code>，量每个 chunk 的 gzip 大小，对照 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/2ee9415a88a784ded5dd07b8a1dcc3e8b11a7ec2/scripts/perf/baselines.json" target="_blank" rel="noreferrer">baselines.json</a> 里的<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/2ee9415a88a784ded5dd07b8a1dcc3e8b11a7ec2/CONTEXT.md" target="_blank" rel="noreferrer">确定性预算</a>——初始包体 ≤400 KiB gzip，异步 chunk ≤500 KiB，<code>markdown</code> 必须是懒加载 chunk。报告落在 <code>.scratch/perf/bundle-report.json</code>，超标即失败，列出每个违规项。“初始集”取 index.html 的 <code>&lt;script&gt;</code> 标签<strong>加上 modulepreload 链接</strong>——入口静态导入的 chunk 不允许伪装成异步 chunk，躲进更宽松的那半预算。</p><p>当前实测：初始 174.4 KiB（<code>index.js</code>），懒加载 46.7 KiB（<code>markdown-content.js</code>）。预算留了约一倍余量，不是按现状贴地飞。</p><h2 id="_3-基线调整-预算怎么改" tabindex="-1">3. 基线调整：预算怎么改 <a class="header-anchor" href="#_3-基线调整-预算怎么改" aria-label="Permalink to &quot;3. 基线调整：预算怎么改&quot;">​</a></h2><p>预算是人定的，会被调整，但只有一条正当路径：<strong>在同一 PR 里给出测量证据与理由</strong>。在引入回归的变更里顺手调高预算让门禁通过，是这条规则明确禁止的事——门禁的存在意义就是让这次退化被看见、被讨论。步骤：</p><ol><li>用 <code>just perf</code> 取得变更前后的完整测量（预算测试 + 包体 + 查询计划报告）。</li><li>在 baselines.json 里同时改预算值与 <code>firstMeasured</code> 的实测记录，说明新的数字从哪来。</li><li>PR 描述里给出对比：旧预算、旧实测、新预算、新实测。</li></ol><h2 id="_4-查询计划报告-证据-不是门槛" tabindex="-1">4. 查询计划报告：证据，不是门槛 <a class="header-anchor" href="#_4-查询计划报告-证据-不是门槛" aria-label="Permalink to &quot;4. 查询计划报告：证据，不是门槛&quot;">​</a></h2><p><code>just perf-ci</code> 的第二半是 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/2ee9415a88a784ded5dd07b8a1dcc3e8b11a7ec2/scripts/perf-query-plans.mjs" target="_blank" rel="noreferrer">perf-query-plans.mjs</a>：在一次性数据库里按 10 / 1 000 / 100 000 三档播种，对两种列表形态跑 <code>EXPLAIN ANALYZE</code>，把规划器实际做的事写进 <code>.scratch/perf/query-plans.json</code>。SQL 从 <code>list_documents</code> 镜像而来（脚本里有 keep-in-sync 注释）；报告<strong>只记录，不失败</strong>——规范 §17.2 说得直接：不能把所有 Seq Scan 一律判错。一个阅读时的注意点：psql 把参数内联成字面量，规划器的选择可能与 sqlx 预编译语句路径略有差异——这份报告看的是形态与量级，不是生产路径的复刻。</p><p>首份基线如实记录了一个反直觉的事实（本地实测值，随机器与数据分布浮动——基线的意义是留下可对比的起点，不是承诺这些毫秒数）：</p><table tabindex="0"><thead><tr><th>档位</th><th>个人列表</th><th>按库列表</th></tr></thead><tbody><tr><td>10 行</td><td>0.1 ms，1 次 Seq Scan</td><td>0.23 ms，1 次 Seq Scan</td></tr><tr><td>1 000 行</td><td>0.74 ms，1 次 Seq Scan</td><td>0.27 ms，0 次 Seq Scan</td></tr><tr><td>100 000 行</td><td>56.6 ms，1 次 Seq Scan</td><td>0.27 ms，0 次 Seq Scan</td></tr></tbody></table><p>按库列表全程走索引（Incremental Sort + Nested Loop + Index Only Scan），成本平坦。个人列表在 10 万行时被规划器选成 Seq Scan + top-N 排序：单用户 <code>&#39;%&#39;</code> 模式下它认为这样最快，10 万行也只要约 57 ms——本版把它如实记下，不修也不拦；什么时候这个数字值得动手，由带着报告的 PR 决定。这正是一份报告与一道门禁的分工。</p><h2 id="_5-在哪跑、删例后剩什么" tabindex="-1">5. 在哪跑、删例后剩什么 <a class="header-anchor" href="#_5-在哪跑、删例后剩什么" aria-label="Permalink to &quot;5. 在哪跑、删例后剩什么&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> perf</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 先打印命令索引与基线指针，再跑完整确定性证据：预算测试 + 包体门禁 + 查询计划报告</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> perf-ci</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 包体门禁 + 查询计划报告；just check 内含这一步（规范 §21 的主门禁覆盖 perf-ci）</span></span></code></pre></div><p>预算测试随 <code>just test</code> 的后端套件运行；<code>just check</code> 调用 <code>just perf-ci</code>，主门禁由此覆盖全部确定性性能预算。CI 不再单设 perf 步——<code>just check</code> 通过后把 <code>.scratch/perf/</code> 作为 7 天的 <code>perf-report</code> 产物上传，供评审翻阅。</p><p>删例后的归属：注册预算是 Core，继续被 <code>just check</code> 钉住；文档预算与播种的查询形态随示例退场；查询计划脚本会诚实说明并退出，提示你照同样的骨架 EXPLAIN 自己业务的热查询（见<a href="./example-removal">移除示例</a>）。给新业务写预算时沿用同一套形状——行数断言、语句计数、字节数上限——性能合同的结构不需要重新发明。</p><hr><p>源码版本：<code>2ee9415a88a7</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/2ee9415a88a784ded5dd07b8a1dcc3e8b11a7ec2/docs/tutorials/24-perf-gates.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,24)])])}const u=a(d,[["render",o]]);export{b as __pageData,u as default};
